//! User-visible strings, in Chinese and English.
//!
//! The catalog is generated by one macro invocation so the enum, both language
//! tables and the parity tests all come from a single list — the two languages
//! cannot drift apart, and a missing translation is a compile error.
//!
//! Note the distinction between two languages:
//!
//! * **UI language** (`lang`) — which catalog is used. The user can force it.
//! * **Text locale** (`dwrite_locale`) — handed to DirectWrite for every run of
//!   text. This always follows the *system* locale regardless of the UI choice:
//!   it drives font fallback and line breaking, so a Japanese title must be laid
//!   out with a Japanese locale even when the menus are in English.

use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::OnceLock;
use windows::{core::PCWSTR, Win32::Globalization::GetUserDefaultLocaleName};

macro_rules! strings {
    ($($key:ident => $zh:expr, $en:expr;)*) => {
        /// Every user-visible string in the program.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        #[repr(usize)]
        pub enum Key { $($key),* }

        impl Key {
            /// All keys in declaration order. Used by the catalog tests.
            pub const ALL: &'static [Key] = &[$(Key::$key),*];
        }

        const ZH: &[&str] = &[$($zh),*];
        const EN: &[&str] = &[$($en),*];
    };
}

