impl Key {
    fn index(self) -> usize {
        self as usize
    }
}

/// Which catalog is in use.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Lang {
    Zh,
    En,
}

static CURRENT: AtomicU8 = AtomicU8::new(0);
static SYSTEM: AtomicU8 = AtomicU8::new(0);
static LOCALE_W: OnceLock<Vec<u16>> = OnceLock::new();

/// The locale name Windows reports for the current user, e.g. `zh-CN`, `ja-JP`.
/// Falls back to `en-US` when the API fails.
pub fn system_locale_name() -> String {
    unsafe {
        // LOCALE_NAME_MAX_LENGTH is 85.
        let mut buf = [0u16; 85];
        let n = GetUserDefaultLocaleName(&mut buf);
        if n > 1 {
            return String::from_utf16_lossy(&buf[..(n as usize - 1)]);
        }
    }
    "en-US".to_string()
}

fn lang_from_locale(name: &str) -> Lang {
    let lower = name.to_ascii_lowercase();
    if lower.starts_with("zh") {
        Lang::Zh
    } else {
        Lang::En
    }
}

/// Resolves the language to use and installs it. Call once during startup.
///
/// `choice` is the raw `language` config value: `auto`, `zh-CN` or `en`.
/// Returns the language actually selected.
pub fn init(choice: &str) -> Lang {
    let system = lang_from_locale(&system_locale_name());
    SYSTEM.store(
        match system {
            Lang::Zh => 0,
            Lang::En => 1,
        },
        Ordering::Relaxed,
    );

    let lang = match choice {
        "zh-CN" | "zh" => Lang::Zh,
        "en" | "en-US" => Lang::En,
        _ => system,
    };
    set_lang(lang);
    lang
}

pub fn set_lang(lang: Lang) {
    CURRENT.store(
        match lang {
            Lang::Zh => 0,
            Lang::En => 1,
        },
        Ordering::Relaxed,
    );
}

pub fn current() -> Lang {
    if CURRENT.load(Ordering::Relaxed) == 1 {
        Lang::En
    } else {
        Lang::Zh
    }
}

/// The system language, ignoring any user override.
pub fn system_lang() -> Lang {
    if SYSTEM.load(Ordering::Relaxed) == 1 {
        Lang::En
    } else {
        Lang::Zh
    }
}

/// The config value that reproduces the current UI language.
pub fn current_choice() -> &'static str {
    match current() {
        Lang::Zh => "zh-CN",
        Lang::En => "en",
    }
}

pub fn tr(key: Key) -> &'static str {
    match current() {
        Lang::Zh => ZH[key.index()],
        Lang::En => EN[key.index()],
    }
}

/// Substitutes `{}` placeholders in order. Extra arguments are ignored and a
/// missing argument leaves the placeholder empty, so this never panics.
pub fn tr_fmt(key: Key, args: &[&str]) -> String {
    let template = tr(key);
    let mut out = String::with_capacity(template.len() + 32);
    let mut parts = template.split("{}");
    if let Some(first) = parts.next() {
        out.push_str(first);
    }
    for (i, part) in parts.enumerate() {
        if let Some(arg) = args.get(i) {
            out.push_str(arg);
        }
        out.push_str(part);
    }
    out
}

/// `tr_fmt` for the common single-number case.
pub fn tr_num(key: Key, n: usize) -> String {
    tr_fmt(key, &[&n.to_string()])
}

/// The locale handed to DirectWrite for text layout. Always the system locale:
/// this drives font fallback, so it must not follow the UI language override.
pub fn dwrite_locale() -> PCWSTR {
    let buf = LOCALE_W.get_or_init(|| {
        let mut w: Vec<u16> = system_locale_name().encode_utf16().collect();
        w.push(0);
        w
    });
    PCWSTR(buf.as_ptr())
}

#[cfg(test)]
mod tests {
    use super::*;
    // The catalog keys are enum variants; bring them in unqualified for the
    // assertions below.
    use super::Key::*;
    use std::sync::Mutex;

    /// The current language is process-global, so any test that changes it has to
    /// hold this lock or it will race the other one.
    static LANG_LOCK: Mutex<()> = Mutex::new(());

    fn lock_lang() -> std::sync::MutexGuard<'static, ()> {
        LANG_LOCK.lock().unwrap_or_else(|e| e.into_inner())
    }

    #[test]
    fn catalogs_have_matching_lengths() {
        assert_eq!(ZH.len(), Key::ALL.len(), "zh table is out of sync");
        assert_eq!(EN.len(), Key::ALL.len(), "en table is out of sync");
    }

    #[test]
    fn no_translation_is_empty() {
        for (i, key) in Key::ALL.iter().enumerate() {
            assert!(!ZH[i].is_empty(), "{key:?} has no Chinese text");
            assert!(!EN[i].is_empty(), "{key:?} has no English text");
        }
    }

    #[test]
    fn locale_detection_handles_chinese_variants() {
        assert_eq!(lang_from_locale("zh-CN"), Lang::Zh);
        assert_eq!(lang_from_locale("zh-Hans-CN"), Lang::Zh);
        assert_eq!(lang_from_locale("zh-TW"), Lang::Zh);
        assert_eq!(lang_from_locale("en-US"), Lang::En);
        assert_eq!(lang_from_locale("ja-JP"), Lang::En);
        assert_eq!(lang_from_locale(""), Lang::En);
    }

    #[test]
    fn explicit_choice_overrides_detection() {
        let _guard = lock_lang();
        assert_eq!(init("zh-CN"), Lang::Zh);
        assert_eq!(init("en"), Lang::En);
        // Anything unrecognised falls back to the system language.
        assert_eq!(init("klingon"), system_lang());
    }

    #[test]
    fn formatting_substitutes_in_order() {
        let _guard = lock_lang();
        set_lang(Lang::En);
        assert_eq!(tr_num(SetFound, 42), "Found 42 music files");
        assert_eq!(
            tr_fmt(MonitorItem, &["2"]),
            "Monitor 2",
            "single placeholder"
        );
        // Missing arguments must not panic.
        set_lang(Lang::Zh);
        assert_eq!(tr_fmt(MonitorItem, &[]), "显示器 ");
    }

    #[test]
    fn dwrite_locale_is_null_terminated() {
        let p = dwrite_locale();
        // `as_wide` stops before the terminator, so check the raw byte after it.
        let s = unsafe { p.as_wide() };
        assert!(!s.is_empty(), "locale must not be empty");
        let byte_after = unsafe { *p.as_ptr().add(s.len()) };
        assert_eq!(byte_after, 0, "locale must be NUL terminated");
    }
}
